"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[61451],{43057:e=>{e.exports=JSON.parse('{"label":"rollups","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.8/tags/rollups","allTagsPath":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.8/tags","count":5,"items":[{"id":"version-0.8/components","title":"Components","description":"As explained in the previous section, the Cartesi Rollups framework achieves scalability by moving the bulk of the computation outside the blockchain, using the ledger as a data source but not as an execution environment. As such, the solution contains both on-chain (L1) and off-chain (L2) components.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.8/components"},{"id":"version-0.8/dapp-architecture","title":"dApp architecture","description":"Borrowing from familiar mainstream terminology, from a developer\u2019s point of view a Cartesi dApp is developed by implementing two main components: a front-end and a back-end.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.8/dapp-architecture"},{"id":"version-0.8/dapp-life-cycle","title":"dApp life cycle","description":"Now that we have described the architecture of a Cartesi dApp and how the front-end and back-end communicate with the Cartesi Rollups framework, let\u2019s step back a bit to discuss how a dApp can be implemented in practice.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.8/dapp-life-cycle"},{"id":"version-0.8/overview","title":"Overview","description":"The combination of an Optimistic Rollups framework and the Cartesi Machine Emulator enables the development of smart contracts and dApps using any package or library that is available for Linux. This allows developers to break free from the scalability limitations of the Ethereum Virtual Machine (EVM), and brings the rise of a new blockchain era to handle real-life and complex use-cases.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.8/overview"},{"id":"version-0.8/http-api","title":"Rollups HTTP APIs","description":"In a Cartesi dApp, the front-end and back-end parts of the application communicate with each other through the Rollups framework via a set of HTTP APIs.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.8/http-api"}]}')}}]);